package dev.pocketengine.features.devices;

import dev.pocketengine.core.RunControl;
import dev.pocketengine.store.TaskStore;
import dev.pocketengine.store.TaskStoreDeviceTasks;
import java.util.Map;
import java.util.UUID;
import org.json.JSONArray;
import org.json.JSONObject;

/** Native original-owner/A-proof range -> unique wire adapter. No model template or boolean grant. */
public final class DeviceNativeRoute implements DeviceCapabilityPort.NativeRoute {
    @FunctionalInterface public interface Exchange {
        DeviceCapabilityPort.Reply once(String targetDeviceId,DeviceTaskEnvelope request,RunControl cancellation)throws Exception;
        default DeviceCapabilityPort.Reply once(String targetDeviceId,DeviceTaskEnvelope request,TaskStoreDeviceTasks.OutboundSendTicket ticket,RunControl cancellation)throws Exception{throw new SecurityException("传输未安装原native发送票据，未走raw副作用通道");}
    }
    private final NativeDeviceTaskScopeHost.NativeOptionSource materialSource;
    private final TaskStore tasks;private final DeviceIdentity.LocalIdentity local;private final TaskStoreDeviceTasks.OwnerRouteApproval approval;
    private final PairingCoordinator.OutgoingGrant grant;private final RunControl original;private final Exchange transport;private final String taskId,runId;private final int epoch;
    private final Map<String,String> effects;private final java.util.Map<String,PairingCoordinator.HistoryQuery> queries=new java.util.concurrent.ConcurrentHashMap<>();
    public DeviceNativeRoute(TaskStore tasks,DeviceIdentity.LocalIdentity local,TaskStoreDeviceTasks.OwnerRouteApproval approval,RunControl original,Exchange transport)throws Exception{this(tasks,local,approval,original,transport,null);}
    public DeviceNativeRoute(TaskStore tasks,DeviceIdentity.LocalIdentity local,TaskStoreDeviceTasks.OwnerRouteApproval approval,RunControl original,Exchange transport,NativeDeviceTaskScopeHost.NativeOptionSource materialSource)throws Exception{
        this.materialSource=materialSource;
        this.tasks=java.util.Objects.requireNonNull(tasks);this.local=java.util.Objects.requireNonNull(local);this.approval=java.util.Objects.requireNonNull(approval);this.original=java.util.Objects.requireNonNull(original);this.transport=java.util.Objects.requireNonNull(transport);grant=approval.receivingGrant();effects=approval.toolEffects();var run=original.hostRunIdentity();if(run==null)throw new SecurityException("路由没有原TaskStore run");taskId=run.taskId();runId=run.runId();epoch=run.epoch();if(!local.deviceId().equals(grant.grant().getString("peerDeviceId")))throw new SecurityException("本机native签名身份不是目标owner grant受众");requireCurrent(System.currentTimeMillis());
    }
    @Override public String routeId(){return approval.routeId();}
    @Override public String targetDeviceId(){return grant.targetDeviceId();}
    @Override public String parentGoal(){return approval.parentGoal();}
    @Override public boolean supportsFunction(String function){return function.equals("device_operation_get")||function.equals(approval.kind().equals("goal")?"device_delegate_goal":"device_invoke_tool");}
    @Override public TaskStoreDeviceTasks.OwnerRouteApproval reservationApproval(){return approval;}
    @Override public PairingCoordinator.OutgoingGrant receivingGrant(){return grant;}
    @Override public void requireCurrent(long now)throws Exception{approval.checkCurrent(original);grant.checkCurrent(now);if(!original.matchesHostRun(taskId,runId,epoch))throw new SecurityException("原父执行代次变化");}
    @Override public String effect(String tool)throws Exception{requireCurrent(System.currentTimeMillis());String effect=effects.get(tool);if(effect==null||!PairingCoordinator.contains(grant.grant().getJSONArray("toolNames"),tool))throw new SecurityException("原native范围没有这个准确工具声明");return effect;}
    @Override public JSONObject invocationContracts()throws Exception{requireCurrent(System.currentTimeMillis());JSONObject result=new JSONObject();for(var item:effects.entrySet())if(item.getValue().equals(DeviceSourceToolContracts.effect(approval.capabilityVersion(),item.getKey()))){JSONArray schemas=switch(item.getKey()){case "workspace.receive"->DeviceSelectedFileTransfer.contracts(approval.view());case "workspace.project.receive"->DeviceSelectedProjectTransfer.contracts(approval.view());case "workspace.project.confirm"->projectConfirmContracts();case "workspace.project.export"->projectExportContracts();default->DeviceSourceToolContracts.variants(approval.capabilityVersion(),item.getKey());};if(schemas.length()>0)result.put(item.getKey(),schemas);}return result;}
    @Override public void validateArguments(String function,JSONObject arguments)throws Exception{
        requireCurrent(System.currentTimeMillis());if(function.equals("device_operation_get"))return;
        if(function.equals("device_invoke_tool")!=approval.kind().equals("tool_session")||arguments.getInt("toolBudget")!=approval.toolBudget()||arguments.optInt("modelBudget",0)!=approval.modelBudget())throw new SecurityException("工具/Goal种类或固定累计份额不是原owner/A范围，不能逐step改额度");
        if(function.equals("device_delegate_goal")&&!approval.parentGoal().equals(arguments.optString("goal")))throw new SecurityException("本版只分享原owner已审阅目标文字，不将模型私有上下文伪装新Goal");
        if(arguments.has("contextSnapshot"))throw new SecurityException("共享材料尚未原native选材批准，不能由模型JSON附带私人上下文");
        if(function.equals("device_invoke_tool")){String tool=arguments.getString("toolName");effect(tool);if(tool.equals("workspace.project.export")){JSONObject args=arguments.getJSONObject("arguments");if(!DeviceProtocol.objectKeys(args).equals(java.util.Set.of("receiveOperationId")))throw new SecurityException("只能回读本任务原receive操作");requireProjectMaterial(args.getString("receiveOperationId"));}
        else if(tool.equals("workspace.project.confirm")){JSONObject args=arguments.getJSONObject("arguments");if(!DeviceProtocol.objectKeys(args).equals(java.util.Set.of("receiveOperationId")))throw new SecurityException("只能指明已原生二次审批的receive操作");requireProjectConfirmation(args.getString("receiveOperationId"));}
        else if(tool.equals("workspace.project.receive")){JSONObject args=arguments.getJSONObject("arguments");if(!DeviceProtocol.objectKeys(args).equals(java.util.Set.of("materialId"))||materialSource==null)throw new SecurityException("只准原主人所选项目materialId");DeviceSelectedProjectTransfer.require(tasks,materialSource.localModule(),DeviceSelectedProjectTransfer.selected(approval.view(),args.getString("materialId")),original);}
        else if(tool.equals("workspace.receive")){JSONObject args=arguments.getJSONObject("arguments");if(!DeviceProtocol.objectKeys(args).equals(java.util.Set.of("materialId"))||materialSource==null)throw new SecurityException("只能指定原主人选中的materialId");DeviceSelectedFileTransfer.revalidate(materialSource.attachmentBook(),DeviceSelectedFileTransfer.selected(approval.view(),args.getString("materialId")),original);}else DeviceSourceToolContracts.validate(approval.capabilityVersion(),tool,arguments.getJSONObject("arguments"));}
    }
    private void requireProjectMaterial(String receiveOperation)throws Exception{
        requireCurrent(System.currentTimeMillis());if(materialSource==null)throw new SecurityException("原项目模块不可用");
        JSONObject selected=tasks.deviceTasks().approvedProjectMaterial(approval,receiveOperation,original);
        DeviceSelectedProjectTransfer.require(tasks,materialSource.localModule(),selected,original);
    }
    private JSONObject requireProjectConfirmation(String receiveOperation)throws Exception{
        JSONObject exact=tasks.deviceTasks().requireProjectImportConfirmation(approval,receiveOperation,original);
        requireProjectMaterial(receiveOperation);return exact;
    }
    private void requireProjectWire(DeviceTaskEnvelope request)throws Exception{
        String tool=request.toolInvocation().toolName();String operation=request.toolInvocation().arguments().getString("receiveOperationId");
        if(tool.equals("workspace.project.confirm")){
            JSONObject exact=requireProjectConfirmation(operation);
            if(!DeviceProtocol.canonical(exact).equals(DeviceProtocol.canonical(request.toolInvocation().arguments())))throw new SecurityException("原审批确认wire已变化");
        }else requireProjectMaterial(operation);
    }
    private JSONArray projectExportContracts()throws Exception{JSONArray ids=tasks.deviceTasks().projectExportInputs(approval,original);if(ids.length()==0)return new JSONArray();return new JSONArray().put(new JSONObject().put("type","object").put("properties",new JSONObject().put("receiveOperationId",new JSONObject().put("type","string").put("enum",ids))).put("required",new JSONArray().put("receiveOperationId")).put("additionalProperties",false));}
    private JSONArray projectConfirmContracts()throws Exception{JSONArray out=new JSONArray(),approved=tasks.deviceTasks().projectImportConfirmations(approval,original);for(int i=0;i<approved.length();i++)out.put(new JSONObject().put("type","object").put("properties",new JSONObject().put("receiveOperationId",new JSONObject().put("type","string").put("enum",new JSONArray().put(approved.getJSONObject(i).getString("receiveOperationId"))))).put("required",new JSONArray().put("receiveOperationId")).put("additionalProperties",false));return out;}
    @Override public DeviceTaskEnvelope request(String method,JSONObject arguments,String operation,int tools,int models,JSONObject observation,RunControl control)throws Exception{
        if(control!=original||!method.equals("operation.get")||tools!=0||models!=0||observation!=null)throw new SecurityException("执行只能先原SQL预留；query只准准确原operation");requireCurrent(System.currentTimeMillis());return historyQuery(operation).envelope();
    }
    private PairingCoordinator.HistoryQuery historyQuery(String operation)throws Exception{
        long now=System.currentTimeMillis();queries.entrySet().removeIf(entry->entry.getValue().envelope().deadline()<=now);if(queries.size()>=32)throw new SecurityException("原只读查询尚未收束");var query=grant.historyQuery(local,"operation.get",operation,approval.resourceBinding(),now,5000,null);queries.put(query.envelope().requestId(),query);return query;
    }
    @Override public JSONObject prepare(String method,JSONObject arguments,String operation,int tools,int models,JSONObject observation,RunControl control)throws Exception{
        if(control!=original)throw new SecurityException("不能替换原父控制器");requireCurrent(System.currentTimeMillis());if(!method.equals(approval.kind().equals("goal")?"task.submitGoal":"tool.invoke")||tools!=approval.toolBudget()||models!=approval.modelBudget()||arguments.has("contextSnapshot"))throw new SecurityException("本机原范围不允许此目标/份额/未选择材料");
        JSONObject task=tasks.get(taskId,false),origin=task.optJSONObject("origin"),receiving=grant.grant();long deadline=Math.min(approval.deadline(),Math.min(grant.deadline(),tasks.taskExecutionDeadline(taskId,runId,epoch)));String originating=local.deviceId(),root=taskId;JSONArray visited=new JSONArray().put(local.deviceId()),chain=new JSONArray();
        if(origin!=null){if(!approval.forwarded()||!"paired_device".equals(origin.optString("kind")))throw new SecurityException("非私人来源只能沿原已验证A proof，不降级owner");originating=origin.getString("originDeviceId");root=task.getString("rootTaskId");JSONObject scope=task.getJSONObject("deviceExecutionScope"),proof=scope.optJSONObject("forwardingProof");if(proof==null)throw new SecurityException("A未授予继续转派");visited=new JSONArray(scope.getJSONArray("visitedDevices").toString()).put(local.deviceId());chain=new JSONArray(scope.getJSONArray("delegationChain").toString()).put(proof);}
        if(!PairingCoordinator.contains(receiving.getJSONArray("capabilities"),method))throw new SecurityException("目标owner未授予此方法");String allocation=DeviceProtocol.allocationId(taskId,targetDeviceId(),approval.resourceBinding(),approval.kind(),approval.kind().equals("goal")?operation:null);
        JSONObject payload=new JSONObject(arguments.toString());if(method.equals("task.submitGoal")&&!approval.parentGoal().equals(payload.optString("goal")))throw new SecurityException("Goal不是原owner已选择的目标文字");
        JSONObject envelope=new JSONObject().put("protocolVersion",DeviceProtocol.VERSION).put("protocolProfile",DeviceProtocol.PROFILE).put("messageType",method.equals("tool.invoke")?"ToolInvocation":"GoalSubmission").put("method",method).put("requestId",UUID.randomUUID().toString()).put("operationId",operation).put("rootTaskId",root).put("parentTaskId",taskId).put("localTaskId",allocation).put("originDeviceId",originating).put("callerDeviceId",local.deviceId()).put("targetDeviceId",targetDeviceId()).put("runId",runId).put("attempt",epoch).put("executorEpoch",epoch).put("instanceId",grant.targetInstanceId()).put("grantId",grant.grantId()).put("authorizationEpoch",grant.authorizationEpoch()).put("deadline",deadline).put("budget",new JSONObject().put("allocationId",allocation).put("toolCalls",tools).put("modelCalls",models)).put("visitedDevices",visited).put("maxDelegationDepth",2).put("delegationChain",chain).put("capabilityVersion",approval.capabilityVersion()).put("resourceBinding",approval.resourceBinding()).put("traceId",root).put("arguments",payload);if(observation!=null)envelope.put("observationRef",new JSONObject(observation.toString()));
        if(method.equals("task.submitGoal")&&approval.permitsForwarding()){
            if(origin!=null)throw new SecurityException("本版仅A->B->C/D两条边，B不能新签A的权限");JSONObject forwarding=receiving.getJSONObject("forwardingScope"),range=approval.view();JSONArray targets=new JSONArray(),resources=new JSONArray(),shares=range.getJSONArray("downstreamShares");for(int i=0;i<shares.length();i++){JSONObject share=shares.getJSONObject(i);if(!PairingCoordinator.contains(targets,share.getString("targetDeviceId")))targets.put(share.getString("targetDeviceId"));if(!PairingCoordinator.resourceContains(resources,share.getJSONObject("resourceBinding")))resources.put(share.getJSONObject("resourceBinding"));}
            JSONObject proof=new JSONObject().put("protocolVersion",DeviceProtocol.VERSION).put("protocolProfile",DeviceProtocol.PROFILE).put("messageType","DelegationProof").put("issuerDeviceId",local.deviceId()).put("delegateDeviceId",targetDeviceId()).put("targetResources",targetResources(shares)).put("rootTaskId",root).put("parentTaskId",DeviceProtocol.receiverTaskId(envelope)).put("grantId",grant.grantId()).put("authorizationEpoch",grant.authorizationEpoch()).put("capabilities",forwarding.getJSONArray("capabilities")).put("toolNames",forwarding.getJSONArray("toolNames")).put("toolBudget",tools).put("modelBudget",models).put("deadline",deadline).put("remainingDepth",0).put("previousProofDigest","").put("sourceAllocationId",allocation).put("targetShares",approval.sourceTargetShares(local.deviceId(),allocation));payload.put("delegationAuthorization",proof);
        }
        if(method.equals("tool.invoke")&&payload.optString("toolName").equals("workspace.receive")){
            if(materialSource==null)throw new SecurityException("原选材器未安装");JSONObject file=DeviceSelectedFileTransfer.selected(approval.view(),payload.getJSONObject("arguments").getString("materialId"));DeviceSelectedFileTransfer.revalidate(materialSource.attachmentBook(),file,original);
            payload.put("arguments",new JSONObject().put("path",file.getString("path")).put("expectedVersion",file.getString("expectedVersion")).put("artifact",DeviceSelectedFileTransfer.descriptor(file,envelope,local)));
            DeviceSourceToolContracts.validate(approval.capabilityVersion(),"workspace.receive",payload.getJSONObject("arguments"));
        }
        if(method.equals("tool.invoke")&&payload.optString("toolName").equals("workspace.project.receive")){
            if(materialSource==null)throw new SecurityException("原项目模块未安装");JSONObject project=DeviceSelectedProjectTransfer.selected(approval.view(),payload.getJSONObject("arguments").getString("materialId"));DeviceSelectedProjectTransfer.require(tasks,materialSource.localModule(),project,original);
            payload.put("arguments",new JSONObject().put("path",project.getString("path")).put("expectedVersion","absent").put("artifact",DeviceSelectedProjectTransfer.descriptor(project,envelope,local)));DeviceSourceToolContracts.validate(approval.capabilityVersion(),"workspace.project.receive",payload.getJSONObject("arguments"));
        }
        if(method.equals("tool.invoke")&&payload.optString("toolName").equals("workspace.project.confirm"))payload.put("arguments",requireProjectConfirmation(payload.getJSONObject("arguments").getString("receiveOperationId")));
        if(method.equals("tool.invoke")&&payload.optString("toolName").equals("workspace.project.export"))requireProjectMaterial(payload.getJSONObject("arguments").getString("receiveOperationId"));
        envelope.put("argumentsDigest",DeviceProtocol.argumentsDigest(envelope));return envelope;
    }
    private static JSONArray targetResources(JSONArray shares)throws Exception{JSONArray result=new JSONArray();for(int i=0;i<shares.length();i++){JSONObject share=shares.getJSONObject(i);result.put(new JSONObject().put("targetDeviceId",share.getString("targetDeviceId")).put("resourceBinding",share.getJSONObject("resourceBinding")));}DelegationGrant.validateTargetResources(result);return result;}
    @Override public DeviceTaskEnvelope finalizeReserved(JSONObject draft,TaskStoreDeviceTasks.ChildReservation reservation)throws Exception{requireCurrent(System.currentTimeMillis());reservation.requireIntent(draft);JSONObject value=new JSONObject(draft.toString()),proof=value.getJSONObject("arguments").optJSONObject("delegationAuthorization");if(proof!=null){if(!approval.permitsForwarding()||approval.forwarded()||proof.has("signature"))throw new SecurityException("不是A原native首次预留后签名");value.getJSONObject("arguments").put("delegationAuthorization",DelegationGrant.sign(local,proof));value.put("argumentsDigest",DeviceProtocol.argumentsDigest(value));}return DeviceProtocol.parseRequest(DeviceProtocol.canonicalBytes(value));}
    @Override public DeviceCapabilityPort.Reply exchange(DeviceTaskEnvelope request,RunControl cancellation)throws Exception{if(!request.method().equals("operation.get"))throw new SecurityException("执行不能使用raw发送");if(!queries.containsKey(request.requestId()))throw new SecurityException("不是本路由native新鲜只读query");return transport.once(targetDeviceId(),request,cancellation);}
    @Override public DeviceCapabilityPort.Reply exchange(DeviceTaskEnvelope request,TaskStoreDeviceTasks.OutboundSendTicket ticket,RunControl cancellation)throws Exception{requireCurrent(System.currentTimeMillis());if(cancellation!=original||!request.targetDeviceId().equals(targetDeviceId())||!request.callerDeviceId().equals(local.deviceId()))throw new SecurityException("原出站受众已变化");java.util.Objects.requireNonNull(ticket);if(request.method().equals("tool.invoke")&&(request.toolInvocation().toolName().equals("workspace.project.confirm")||request.toolInvocation().toolName().equals("workspace.project.export"))){requireProjectWire(request);ticket.installNativeWriteGuard(()->requireProjectWire(request));}return transport.once(targetDeviceId(),request,ticket,cancellation);}
    @Override public void requireReplyPeer(DeviceIdentity.AuthenticatedPeer actual,DeviceTaskEnvelope request)throws Exception{PairingCoordinator.HistoryQuery query=queries.remove(request.requestId());if(query!=null)query.requireTargetPeer(actual,System.currentTimeMillis());else grant.requireTargetPeer(actual);}
    @Override public void acceptedTransfer(JSONObject wire,DeviceCapabilityPort.Reply actual,JSONObject receipt)throws Exception{
        JSONObject invocation=wire.optJSONObject("arguments");if(invocation!=null&&"workspace.project.receive".equals(invocation.optString("toolName"))){sendProject(wire,actual,receipt);return;}if(invocation==null||!"workspace.receive".equals(invocation.optString("toolName")))return;
        JSONObject status=receipt.getJSONObject("payload");if(!"awaiting_bytes".equals(status.optString("phase")))return;
        if(materialSource==null)throw new SecurityException("原bulk sender不可用");JSONObject args=invocation.getJSONObject("arguments"),descriptor=args.getJSONObject("artifact");var ref=dev.pocketengine.features.devices.transport.DeviceArtifactTransfer.fromWireDescriptor(descriptor);
        JSONObject file=DeviceSelectedFileTransfer.selected(approval.view(),ref.artifactId);
        if(!args.getString("path").equals(file.getString("path"))||!args.getString("expectedVersion").equals(file.getString("expectedVersion"))||!ref.sha256.equals(file.getString("sha256"))||ref.bytes!=file.getLong("size")||!ref.transferId.equals(status.optString("transferId"))||!ref.sha256.equals(status.optString("sha256"))||ref.bytes!=status.optLong("bytes",-1)||status.optLong("maximumBytes")!=DeviceSelectedFileTransfer.MAX_BYTES)throw new SecurityException("接收确认不是原固定文件/目标/CAS");
        long offset=DeviceProtocol.integer(status.get("verifiedOffset"),"verifiedOffset",0,ref.bytes);
        if(offset!=0&&offset!=ref.bytes)throw new SecurityException("目标游标不是原256KiB分块边界");
        dev.pocketengine.features.devices.transport.DeviceArtifactTransfer.Current current=()->{requireCurrent(System.currentTimeMillis());grant.requireTargetPeer(actual.peer());DeviceSelectedFileTransfer.revalidate(materialSource.attachmentBook(),file,original);};
        current.require();if(offset==ref.bytes&&ref.bytes>0)return;
        byte[] all=materialSource.attachmentBook().readVerifiedSnapshot(file.getString("id"),file.getString("sha256"),original);current.require();
        materialSource.sendSelectedFile(actual.peer(),java.util.UUID.fromString(ref.transferId),offset,all,Math.min(approval.deadline(),wire.getLong("deadline")),current);
        status.put("nativeFileSend",new JSONObject().put("queued",true).put("delivered",false).put("operationId",wire.getString("operationId")).put("nextAction","device_operation_get"));
    }
    private void sendProject(JSONObject wire,DeviceCapabilityPort.Reply actual,JSONObject receipt)throws Exception{
        JSONObject status=receipt.getJSONObject("payload");if(!"awaiting_bytes".equals(status.optString("phase")))return;
        if(materialSource==null)throw new SecurityException("原项目发送器不可用");JSONObject args=wire.getJSONObject("arguments").getJSONObject("arguments");var ref=dev.pocketengine.features.devices.transport.DeviceArtifactTransfer.fromWireDescriptor(args.getJSONObject("artifact"));JSONObject project=DeviceSelectedProjectTransfer.selected(approval.view(),ref.artifactId);
        if(!args.getString("path").equals(project.getString("path"))||!"absent".equals(args.getString("expectedVersion"))||!ref.sha256.equals(project.getString("sha256"))||ref.bytes!=project.getLong("size")||!ref.transferId.equals(status.optString("transferId"))||!ref.sha256.equals(status.optString("sha256"))||ref.bytes!=status.optLong("bytes",-1)||status.optLong("maximumBytes")!=DeviceSelectedProjectTransfer.MAX_BYTES)throw new SecurityException("项目接收确认与原包不符");
        long offset=DeviceProtocol.integer(status.get("verifiedOffset"),"verifiedOffset",0,ref.bytes);int chunk=dev.pocketengine.features.devices.transport.DeviceArtifactTransfer.CHUNK_BYTES;if(offset!=ref.bytes&&offset%chunk!=0)throw new SecurityException("项目游标不是原分块边界");
        dev.pocketengine.features.devices.transport.DeviceArtifactTransfer.Current current=()->{requireCurrent(System.currentTimeMillis());grant.requireTargetPeer(actual.peer());DeviceSelectedProjectTransfer.require(tasks,materialSource.localModule(),project,original);};current.require();if(offset==ref.bytes)return;
        byte[] bytes=DeviceSelectedProjectTransfer.bytes(tasks,materialSource.localModule(),project,original);for(long cursor=offset;cursor<ref.bytes;cursor+=chunk){current.require();byte[] part=java.util.Arrays.copyOfRange(bytes,(int)cursor,(int)Math.min(ref.bytes,cursor+chunk));materialSource.sendSelectedFile(actual.peer(),java.util.UUID.fromString(ref.transferId),cursor,part,Math.min(approval.deadline(),wire.getLong("deadline")),current);}
        status.put("nativeProjectSend",new JSONObject().put("queued",true).put("delivered",false).put("operationId",wire.getString("operationId")).put("nextAction","device_operation_get"));
    }
    /** Native owner fixed-id read after parent cancellation; never authorizes a new effect/run. */
    public DeviceCapabilityPort.Reply reconcile(String operation)throws Exception{var query=historyQuery(operation);DeviceCapabilityPort.Reply result=transport.once(targetDeviceId(),query.envelope(),new RunControl());query.requireTargetPeer(result.peer(),System.currentTimeMillis());queries.remove(query.envelope().requestId());return result;}
}
